/// <summary>
///     The <c>AVAContactPersonDbt_Extension</c> class is the extension for <c>ContactPerson</c>
/// </summary>
[ExtensionOf(tableStr(ContactPerson))]
final class AVAContactPersonDbt_Extension
{
}

Method.Source:
/// <summary>
/// Initialize party of this contact from form record.
/// If record is mapped to DirPartyMap, initialize directly from map, otherwise, contact person will be initialized from other tables.
/// </summary>
/// <param name="_common">
/// Args record will be used to initialize party of contact.
/// </param>
public void initFromArgsRecord(Common _common)
{
    next initFromArgsRecord(_common);

    this.avaUpdateMainResponsibleWorker(_common);
}

/// <summary>
/// calls an avaInit method depending on record
/// </summary>
/// <param name = "_common">Common</param>
public void avaUpdateMainResponsibleWorker(Common _common)
{
    switch (_common.TableId)
    {
        case tableNum(CustTable) :
            this.avaInitFromCustTable(_common);
            break;

        case tableNum(PurchTable) :
            var purchTable = _common as PurchTable;
            this.avaInitFromVendTable(purchTable.vendTable_OrderAccount());
            break;

        case tableNum(SalesQuotationTable) :
            var salesQuotationTable = _common as SalesQuotationTable;
            if (salesQuotationTable.BusRelAccount)
            {
                this.avaInitFromBusRel(smmBusRelTable::find(salesQuotationTable.BusRelAccount));
            }
            else if (salesQuotationTable.CustAccount)
            {
                this.avaInitFromCustTable(CustTable::find(salesQuotationTable.CustAccount));
            }
            break;

        case tableNum(SalesTable) :
            var salesTable = _common as SalesTable;
            this.avaInitFromCustTable(salesTable.custTable_CustAccount());
            break;

        case tableNum(smmBusRelTable) :
            this.avaInitFromBusRel(_common);
            break;

        case tableNum(VendTable) :
            this.avaInitFromVendTable(_common);
            break;
    }
}

/// <summary>
/// custom init method to be called in eventHandler
/// </summary>
/// <param name = "_smmBusRelTable">smmBusRelTable</param>
public void avaInitFromBusRel(smmBusRelTable _smmBusRelTable)
{
    this.MainResponsibleWorker      = _smmBusRelTable.MainContactWorker;
}

/// <summary>
/// custom init method to be called in eventHandler
/// </summary>
/// <param name = "_custTable">CustTable</param>
public void avaInitFromCustTable(CustTable _custTable)
{
    this.MainResponsibleWorker      = _custTable.MainContactWorker;
}

/// <summary>
/// custom init method to be called in eventHandler
/// </summary>
/// <param name = "_vendTable">VendTable</param>
public void avaInitFromVendTable(VendTable _vendTable)
{
    this.MainResponsibleWorker      = _vendTable.MainContactWorker;
}

