    this.Mileage                        = _contactPerson.Mileage;
    this.NDX_CTIContactTransferNot      = _contactPerson.NDX_CTIContactTransferNot;
    this.OfficeLocation                 = _contactPerson.OfficeLocation;
    this.OrganizationalIDNumber         = _contactPerson.OrganizationalIDNumber;
    this.OutlookCategories              = _contactPerson.OutlookCategories;
    this.Profession                     = _contactPerson.Profession;
    this.Sensitivity                    = _contactPerson.Sensitivity;
    this.Spouse                         = _contactPerson.Spouse;
    this.TimeAvailableFrom              = _contactPerson.TimeAvailableFrom;
    this.TimeAvailableTo                = _contactPerson.TimeAvailableTo;
    this.Title                          = _contactPerson.Title;
    this.VIP                            = _contactPerson.VIP;
    this.VendRole                       = _contactPerson.VendRole;
    this.VendorPortalAccessAllowed      = _contactPerson.VendorPortalAccessAllowed;
    this.WebRequestAccess               = _contactPerson.WebRequestAccess;
    this.Party                          = _contactPerson.Party;
}

