/// <summary>
/// returns contact name with connected title
/// </summary>
/// <param name = "_contactPersonId">ContactPersonId</param>
/// <param name = "_languageId">LanguageId</param>
/// <returns>AVAContactName</returns>
public static AVAContactName avaGetContactNameWithTitle(ContactPersonId _contactPersonId, LanguageId _languageId)
{
    AVAContactName  avaContactName;
    ContactPerson   avaContactPerson;
    DirPerson       avaDirPerson;

    avaContactPerson = ContactPerson::find(_contactPersonId);
    if(avaContactPerson)
    {
        avaDirPerson    = DirPerson::find(avaContactPerson.Party);
        avaContactName  = avaDirPerson.avaGetNameWithTitle(_languageId);
        /* replaced with DirPerson.avaGetNameWithTitle()
        DirPersonName avaDirPersonName = DirPersonName::find(avaDirPerson.RecId);
        DirNameAffix avaDirNameAffix = DirNameAffix::findRecId(avaDirPerson.PersonalTitle);
        AVADirNameAffixTranslation avaDirNameAffixTranslation = AVADirNameAffixTranslation::findByDirNameAffixAndLanguage(avaDirPerson.PersonalTitle, _languageId);

        if(avaDirNameAffixTranslation.AVAAffixTxt)
        {
            avaContactName = avaDirNameAffixTranslation.AVAAffixTxt + ' ';
        }
        else if(avaDirNameAffix.AVAKnownAs)
        {
            avaContactName = avaDirNameAffix.AVAKnownAs + ' ';
        }

        avaContactName += avaDirPersonName.FirstName + ' ' + avaDirPersonName.LastName;
        */
    }

    return avaContactName;
}

