/// <summary>
///     AVA <c>avaFindOrCreateCopyNameParty</c> method.
/// </summary>
/// <param name="_party">
///     <c>DirPartyRecId</c> as type
/// </param>
/// <param name="_contactPersonName">
///     <c>ContactPersonName</c> as type
/// </param>
/// <param name="_contactParty">
///     <c>DirPartyRecId</c> as type
/// </param>
/// <returns>
///     <c>ContactPerson</c> as return value
/// </returns>
public static ContactPerson avaFindOrCreateCopyNameParty(   DirPartyRecId       _party, 
                                                            ContactPersonName   _contactPersonName, 
                                                            DirPartyRecId       _contactParty = 0   )
{
    ContactPerson contactPerson;

    if (_party && _contactPersonName)
    {
        contactPerson = ContactPerson::findNameParty(_party, _contactPersonName);
        if (!contactPerson.RecId)
        {
            ttsbegin;
            contactPerson.clear();

            contactPerson.ContactPersonId = NumberSeq::newGetNum(ContactPerson::numRefContactPersonId()).num();
            if(_contactParty)
            {
                contactPerson.Party = _contactParty;
            }
            else
            {
                contactPerson.Party = DirPartyTable::createNew(DirPartyType::Person, _contactPersonName).RecId;
            }
            contactPerson.ContactForParty = _party;
            contactPerson.insert();
            ttscommit;

        }
    }

    return contactPerson;
}
